--
-- Tábla szerkezet ehhez a táblához `cikkek`
--

CREATE TABLE IF NOT EXISTS `cikkek` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `cim` varchar(255) NOT NULL,
  `szoveg` text NOT NULL,
  `diak_id` int(11) NOT NULL,
  `datum` date NOT NULL DEFAULT current_timestamp(),
  `elfogadva` tinyint(1) NOT NULL DEFAULT 0,
  `elfogadta_id` int(11) DEFAULT NULL,
  `kep` longblob DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `diak_id` (`diak_id`),
  KEY `fk_elfogadta` (`elfogadta_id`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8 COLLATE=utf8_hungarian_ci;

--
-- A tábla adatainak kiíratása `cikkek`
--

INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(1, 'A Mesterséges Intelligencia betör az oktatásba', 'A mesterséges intelligencia (MI) egyre nagyobb szerepet kap az életünkben, és az oktatás sem kivétel. Az MI-alapú alkalmazások képesek személyre szabott tanulási élményt nyújtani, automatizálni az adminisztratív feladatokat, és új lehetőségeket teremteni a tanárok és diákok számára.', 19, '2024-08-15', 1, 17, NULL),
(2, 'Zöldebb jövő az iskolában', 'A környezetvédelem egyre fontosabb szerepet játszik a mindennapi életünkben, és a diákok is aktívan részt vesznek a zöldebb jövőért való küzdelemben. Iskolánkban számos kezdeményezés indult a diákok szervezésében, amelyek célja a környezettudatos gondolkodás népszerűsítése és a környezeti terhelés csökkentése. A diákok szelektíven gyűjtik a hulladékot, komposztálják a zöldhulladékot, és energiatakarékos izzókat használnak az osztálytermekben. Emellett rendszeresen szerveznek környezetvédelmi akciókat, mint például szemétszedést a parkban és faültetést az iskola udvarán. A diákok kreativitásukkal és lelkesedésükkel példát mutatnak a felnőtteknek is.', 18, '2024-03-15', 1, 17, NULL),
(3, 'A TikTok világa', 'A TikTok napjaink egyik legnépszerűbb közösségi média platformja, különösen a fiatalok körében. A rövid videók megosztására épülő alkalmazás szórakoztató és kreatív tartalmakat kínál, de vajon a TikTok csak szórakozás, vagy függőséget is okozhat? A TikTok algoritmusának köszönhetően a felhasználók könnyen órákat tölthetnek az alkalmazásban, és elveszíthetik az időérzéküket. A túlzott TikTok használat negatív hatással lehet a tanulásra, az alvásra és a társas kapcsolatokra. A TikTokon megjelenő tartalmak minősége is változó. Fontos, hogy a diákok tudatosan használják a TikTokot, és ne hagyják, hogy az alkalmazás irányítsa az életüket. ', 21, '2024-03-22', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(4, 'A sport ereje', 'Az iskola büszke lehet bajnok úszójára, aki nemrégiben aranyérmet szerzett az országos úszóversenyen. A fiatal sportoló nemcsak tehetséges, hanem szorgalmas és kitartó is. A sport megtanít a küzdelemre, a kitartásra, a csapatmunkára és a fair play-re. A sportoló példát mutat a diákoknak, hogy a kemény munka és a kitartás meghozza gyümölcsét.', 20, '2024-03-29', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(5, 'Az olvasás varázsa', 'Az olvasás egy varázslatos utazás, ami új világokat nyit meg előttünk. A könyvtáros ajánlásával egy olyan könyvet ismerhetünk meg, ami elgondolkodtató, szórakoztató és inspiráló. A könyv egy fiatal lány történetét meséli el, aki egy távoli szigeten él, és felfedezi a természet titkait. A könyv gyönyörűen írja le a természet és az ember kapcsolatát, és arra ösztönöz, hogy óvjuk a környezetünket. A könyvtáros szerint a könyv minden korosztály számára ajánlott, és garantáltan elvarázsolja az olvasókat.', 22, '2024-04-05', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(6, 'Az iskola új robotika szakköre', 'Nagy örömmel jelentjük be, hogy iskolánkban elindult egy új robotika szakkör, melynek célja, hogy a diákok megismerkedjenek a robotika alapjaival, és fejlesszék a programozási, tervezési és problémamegoldó készségeiket. A szakkörben a diákok saját robotokat építhetnek és programozhatnak, részt vehetnek versenyeken, és megismerkedhetnek a robotika legújabb trendjeivel. A robotika szakkör egy remek lehetőség a diákok számára, hogy fejlesszék a kreativitásukat, a logikai gondolkodásukat és a csapatmunkára való képességüket. A szakkör vezetője, Kiss Péter mérnök elmondta, hogy a robotika szakkör célja, hogy a diákok számára egy olyan platformot teremtsenek, ahol kibontakoztathatják a tehetségüket, és felkészüljenek a jövő kihívásaira.', 20, '2024-04-12', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(7, 'Kulturális sokszínűség az iskolában', 'Iskolánkban nagy hangsúlyt fektetünk a kulturális sokszínűségre, és igyekszünk minél több lehetőséget teremteni a diákok számára, hogy megismerjék és megértsék a különböző kultúrákat. A Világ Napja alkalmából iskolánkban egy nagyszabású rendezvényt szerveztünk, ahol a diákok bemutathatták saját kultúrájukat, ételeiket, táncaikat és hagyományaikat. A rendezvényen részt vett a város polgármestere, aki méltatta iskolánk kezdeményezését, és hangsúlyozta a kulturális sokszínűség fontosságát a társadalmunkban.', 18, '2024-04-16', 1, 17, NULL),
(8, 'Életre kelt a színpad', 'A színjátszó kör hatalmas sikert aratott a tegnapi bemutatóval. A klasszikus darab modern feldolgozása, a színészek elhivatottsága és a látványos díszlet együttesen varázslatos élményt nyújtott a nézőknek.', 21, '2024-04-19', 1, 17, NULL),
(9, 'Kórusban az öröm', 'A kórus fantasztikus koncertet adott a városi kórház javára. A diákok lelkesedése és a zene gyógyító ereje felejthetetlen pillanatokat szerzett a betegeknek és az adományozóknak.', 21, '2024-04-26', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(10, 'Az iskola kertje virágzik', 'Az iskola kertje a diákok gondoskodásának köszönhetően színpompás virágokkal teli. A kert nemcsak szép, hanem a biológia órák fontos helyszíne is.', 21, '2024-05-03', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(11, 'Pályaválasztás előtt állsz?', 'A pályaválasztás komoly döntés, ami meghatározza a jövődet. Ebben a cikkben szakemberek adnak tanácsot, hogyan válaszd ki a számodra legmegfelelőbb szakmát. Fontos, hogy figyelembe vedd az érdeklődési körödet, a képességeidet és a munkaerőpiac igényeit. Ne félj kérdezni, és tájékozódj minél alaposabban!', 20, '2024-05-10', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(12, 'Csereprogram Dániában', 'Két diákunk részt vett egy csereprogramban Dániában, és rengeteg élménnyel gazdagodtak. Koppenhága gyönyörű város, a dánok barátságosak, és az oktatás magas színvonalú. A diákok új barátokra tettek szert, és sokat tanultak a dán kultúráról. Ajánljuk mindenkinek a csereprogramot, mert egy életre szóló élmény.', 20, '2024-05-17', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(13, 'A digitális világ árnyoldalai', 'A cyberbullying, vagyis az online zaklatás egyre nagyobb problémát jelent az iskolákban. A diákok a közösségi médián, az üzenetküldő alkalmazásokon és az online játékokban zaklatják egymást. A cyberbullying súlyos lelki sérüléseket okozhat, és akár öngyilkossághoz is vezethet. Fontos, hogy a diákok, a szülők és a tanárok felismerjék a cyberbullying jeleit, és tegyenek ellene. A cyberbullying nem vicc, hanem bűncselekmény!', 18, '2024-05-24', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(14, 'Az iskola legújabb büszkesége', 'Az iskola udvarán okos padok kerültek elhelyezésre, melyek napelemmel működnek, USB-portokkal rendelkeznek és ingyenes wifit biztosítanak a diákok számára. A padok nemcsak kényelmesek, hanem környezetbarátok is.', 19, '2024-05-31', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(15, 'Légy te is tudós!', 'A tudomány nemcsak az iskolában, hanem otthon is érdekes lehet. Ebben a cikkben bemutatunk néhány izgalmas kísérletet, amit egyszerűen elvégezhetsz a konyhádban található alapanyagokkal. Kísérletezz, fedezz fel, és légy te is tudós!', 20, '2024-06-07', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(16, 'Divatbemutató az iskolában', 'A diákok tehetségüket és kreativitásukat mutatták be a divatbemutatón. A ruhák egyediek és stílusosak voltak, a modellek pedig profin vonultak a kifutón. A divatbemutató nagy sikert aratott, és mindenki jól szórakozott.', 22, '2024-06-14', 1, 17, NULL),
(17, 'Interjú a Diákönkormányzat elnökével', 'Az új Diákönkormányzat elnöke ambiciózus tervekkel vág neki a munkának. Célja a diákok érdekeinek képviselete, a programok szervezése és az iskola életének színesítése.', 21, '2024-06-21', 1, 17, NULL),
(19, 'A nyár slágerei', 'Milyen zene szóljon a nyári bulikon, a strandon vagy a kocsiban? Összegyűjtöttük a diákok kedvenc nyári számait egy playlistbe. Hallgasd meg, és találd meg a kedvenceidet!', 22, '2024-07-05', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(20, 'Utazás a csillagok között', 'A planetárium egy varázslatos hely, ahol megismerheted a csillagokat, a bolygókat és a galaxisokat.', 18, '2024-07-12', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(21, 'Készüljünk együtt a vizsgákra!', 'A vizsgaidőszak minden diák számára stresszes időszak. Ebben a cikkben összegyűjtöttük a leghatékonyabb tanulási tippeket, a hatékony időbeosztástól a relaxációs technikákig. Készülj fel a vizsgákra nyugodtan és magabiztosan!', 20, '2024-07-19', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(22, 'Hogyan védekezzünk a nap ellen?', 'A nyári napsütés jót tesz a hangulatunknak, de káros lehet a bőrünknek. Ebben a cikkben bőrgyógyász ad tanácsot, hogyan védekezzünk a nap ellen, és hogyan előzzük meg a leégést és a bőrrákot.', 20, '2024-07-26', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(23, 'Nyári munka', 'A nyári munka jó lehetőség a diákok számára, hogy pénzt keressenek, és tapasztalatot szerezzenek a munka világában. Ebben a cikkben bemutatjuk a legnépszerűbb nyári munkákat, a munkajogi szabályokat és a tippeket a sikeres álláskereséshez.', 19, '2024-08-02', 1, 17, NULL),
(24, 'DIY – Készíts egyedi pólót otthon!', 'Unod a régi pólóidat? Ebben a cikkben bemutatjuk, hogyan készíthetsz egyedi pólókat otthon, egyszerű technikákkal és alapanyagokkal. Legyél kreatív, és alkoss valami különlegeset!', 22, '2024-08-09', 1, 17, NULL),
(25, 'Mi leszel, ha nagy leszel?', 'Megkérdeztük a diákokat, mi szeretnének lenni, ha nagyok lesznek. A válaszok sokszínűek és inspirálóak voltak. Van, aki orvos szeretne lenni, van, aki mérnök, van, aki művész, és van, aki űrhajós. Mindenki álmodozik, és hisz abban, hogy megvalósíthatja a céljait.', 20, '2024-08-16', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(26, 'A legszebb nyári emlékek', 'Lezárult a fotópályázat, és kihirdettük a győzteseket. A képek gyönyörűek és meghatóak voltak, és a nyár legszebb pillanatait örökítették meg. Gratulálunk a győzteseknek, és köszönjük mindenkinek a részvételt!', 18, '2024-08-23', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(27, 'Vissza a padba!', 'Megérkezett az új órarend! Nézd meg, mikor lesz a kedvenc órád és készülj a következő tanévre!', 20, '2024-08-30', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(28, 'Új szabályok a könyvtárban', 'Új szabályok léptek érvénybe a könyvtárban. Olvassátok el figyelmesen!', 21, '2024-09-06', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(29, 'Klíma sztrájk az iskolában!', 'A diákok klíma sztrájkot szerveznek az iskola előtt!', 21, '2024-09-13', 1, 17, NULL),
(30, 'Iskolai Bál közeleg', 'Hamarosan Iskolai Bál!', 21, '2024-04-11', 1, 17, NULL),
(31, 'A zene gyógyító ereje', 'Iskolánk egyik diákja nem csak tehetséges zenész, hanem zeneterapeutaként is tevékenykedik. Az interjúban elmeséli, hogyan segít a zene a betegeknek a gyógyulásban, hogyan fejleszti a zene a kreativitást és az érzelmi intelligenciát, és miért érdemes mindenkinek zenét tanulnia.', 22, '2024-09-20', 1, 17, NULL),
(32, 'Így készülj a matekversenyre!', 'A matekversenyre való felkészülés sok időt és energiát igényel, de a sikerélmény megéri a fáradságot. Iskolánk matekbajnoka elárulja, hogyan készült a versenyre, milyen feladatokat oldott meg, és milyen tippeket ad a többi diáknak.', 21, '2024-09-27', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(33, 'Az őszi szünet legjobb programjai', 'Közeleg az őszi szünet, és sokan nem tudják, mivel töltsék az időt. Összegyűjtöttük a diákok kedvenc őszi programjait, a kirándulástól a filmestig, a múzeumlátogatástól a sütésig. Találd meg a kedvedre valót, és élvezd a szünetet!', 21, '2024-10-04', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(34, 'Hogyan legyél sikeres a prezentációkban?', 'A prezentációk fontos szerepet játszanak a tanulásban és a munka világában. Ebben a cikkben a retorika mestere ad tanácsot, hogyan készíts hatásos prezentációt, hogyan tartsd fenn a közönség figyelmét, és hogyan győzd meg a hallgatókat az igazadról.', 20, '2024-10-11', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(35, 'A tökéletes Halloween parti', 'Szeretnél Halloween partit szervezni, de nem tudod, hogyan kezdj hozzá? Ebben a cikkben bemutatjuk a tökéletes Halloween parti receptjét, a dekorációtól a jelmezekig, a programoktól a nasikig. Készülj fel a borzongásra!', 19, '2024-10-18', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(36, 'A közösségi média hatása a mentális egészségre', 'A közösségi média fontos szerepet játszik a fiatalok életében, de vajon milyen hatással van a mentális egészségre? Ebben a cikkben szakértők véleményét ismerheted meg a közösségi média előnyeiről és hátrányairól, a függőségről és a cyberbullyingról, a testképzavarról és a szorongásról.', 21, '2024-10-25', 1, 17, NULL),
(37, 'A tehetség napja', 'A tehetség napján iskolánk diákjai ismét megmutatták, milyen sokoldalúak és kreatívak. A rendezvényen felléptek énekesek, táncosok, színészek, zenészek és sportolók. A diákok tehetsége és a közönség lelkesedése felejthetetlen élményt nyújtott mindenkinek.', 19, '2024-11-01', 1, 17, NULL),
(38, 'Olvasd el!', 'A novemberi esték tökéletesek az olvasáshoz. Ebben a cikkben bemutatunk néhány könyvet, ami elgondolkodtató, szórakoztató és inspiráló. Találd meg a kedvencedet, és merülj el a könyvek világában!', 22, '2024-11-08', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(39, 'Megérkezett a Mikulás!', 'Iskolánkba is megérkezett a Mikulás!', 21, '2024-12-06', 1, 17, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(40, 'Karácsonyi adomány gyűjtés', 'Idén is karácsonyi adomány gyűjtést szervezetünk! Segíts, hogy minél több rászoruló gyermeknek szebbé tegyük az ünnepeket!', 18, '2024-12-13', 1, 17, NULL);
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(43, 'asd', 'asd', 19, '2025-04-02', 0, NULL, );
INSERT INTO `cikkek` (`id`, `cim`, `szoveg`, `diak_id`, `datum`, `elfogadva`, `elfogadta_id`, `kep`) VALUES
(44, 'admin', 'admin', 17, '2025-04-08', 0, NULL, NULL);

