--
-- Tábla szerkezet ehhez a táblához `diakok`
--

CREATE TABLE IF NOT EXISTS `diakok` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nev` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `evfolyam` varchar(20) DEFAULT NULL,
  `iskola_id` int(11) NOT NULL,
  `szak_id` int(11) DEFAULT NULL,
  `felhasznalonev` varchar(50) NOT NULL,
  `jelszo` varchar(255) NOT NULL,
  `adminE` tinyint(1) NOT NULL DEFAULT 0,
  `profilKep` longblob DEFAULT NULL,
  PRIMARY KEY (`id`),
